# THE REALM'S PAST, one OPEN row added in place (OD-FC-128), round 2 (V-HP-r3 cured): OD-PA-37 THE NEXT CAMPAIGN'S PAST.
import sys
src, dst = sys.argv[1], sys.argv[2]
L = open(src, encoding='utf-8').read().split('\n')
idx = [i for i, s in enumerate(L) if s.startswith('| OD-PA-36 ')]; assert len(idx) == 1
L.insert(idx[0] + 1, "| OD-PA-37 | THE NEXT CAMPAIGN'S PAST (the map program's H47 — a next campaign bound to a world an earlier campaign used — ACCEPTED BY THE OWNER as host work on 2026-10-24, fold OD-FC-138; on the owner's word to the map program of 2026-10-24, as the map's reply quotes it: \"Campaign is just a term we use for the region of the map. So it means multiple or sequentially\"): whether, and how, an earlier campaign's inked past and its played years enter the realm past of a next campaign on the same world — dated under PA8 in years before that campaign's week 0, never compared with or added to a tick or a calendar year, the DM's declared gap and the earlier campaign's span its candidate inputs, as PA14 dates a newcomer at its own founding and OD-PA-32 holds a DM-set anchor OPEN; until it is ruled, a next campaign's past is derived from its own members' dossiers exactly as a first campaign's (a member founded during an earlier campaign's play keeping no past, PA14), and each campaign's past stays its own (the map's per-campaign strip, its H48) — for PA's unit to rule, by delegation unless the owner asks for it | recorded 2026-10-24 (fold §3.1.39); not ruled | **OPEN** |")
open(dst, 'w', encoding='utf-8').write('\n'.join(L)); print('PA row added')
